"""Second edition: retain original concept IDs; rebuild the visual argument."""
from story import M,R,O,P,I,F,D,slider,btn,split
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
N=json.loads((ROOT/'results/generative_i_teaching_numbers.json').read_text())
def graph(kind,controls=''):return D(kind,controls)
def rebuild(slides):
 by={s['id']:s for s in slides}
 def edit(id,body=None,**kw):
  if body is not None:kw['body']=body
  by[id].update(kw)
