 edit('another-digit',O(P('Eight observed test digits','label blue')+I('observed-eight.png','big-strip')+P('Would storing these eight images solve the problem?','large'),0)+O(P('New binary draws from the saved VAE-16','label purple')+I('vae16-common-draws.png','big-strip')+P('Some work better than others. These are the first eight fixed-seed draws.','caption'),1)+O(graph('mother'),2),builds=3,idea='Learn a distribution that can produce new examples.')
 edit('discrete',D('categorical',btn('one','Draw 1')+btn('ten','Draw 10')+btn('hundred','Draw 100')+btn('resample','New seed')+btn('reset','Reset')),builds=5,idea='Compare the observed fractions with 0.2, 0.5 and 0.3.')
 edit('gaussian',D('gaussian',slider('mu','μ',-2,2,0)+slider('sigma','σ',.25,2,1)+slider('count','draws',0,200,35,1)+btn('resample','Fresh draws')),idea='The mean moves the centre; the standard deviation changes the spread.')
 edit('area',D('interval',slider('width','interval half-width',0,2,0,.05)),builds=4,idea='A point has zero probability. An interval can have positive probability.')
 edit('multimodal',D('components',btn('single','One Gaussian')+btn('mixture','All 8 components')),builds=6,idea='The gaps matter as much as the clusters.')
 edit('recipe',graph('mixture-recipe'),builds=4,idea='Choose a centre, draw an offset, add them.')
 edit('learn-density',D('mle',slider('mu','model μ',-1,2,0,.05)),builds=6,idea='',notes='Hold the observations fixed. Start at mean zero and calculate summed log density. Advance to move the mean to .25, then .5. The exact maximum is .5. Ask students whether increasing every density without preserving normalization would define a probability model. The final build introduces maximum likelihood in general.')
 edit('two-abilities',graph('access'),builds=2,idea='A sampler and a tractable density are different kinds of access.')
 edit('language',O(I('attention-decoder.svg','attention-ref')+P('Recall the decoder-only model from Beyond Attention.','caption'),0)+O('<div class="tokens"><span class="token">The</span><span>→</span><span class="token">The dog</span><span>→</span><span class="token">The dog ran</span></div>'+M(r'p(x_1,\ldots,x_T)=\prod_t p(x_t\mid x_{<t})'),1),builds=2)
