 edit('latent-generator',graph('mother'),builds=2,idea='A deterministic generator returns x; our decoder returns Bernoulli probabilities.')
 new('ae-sampling','ae-experiment','Reconstruct a digit. Then try a prior draw.',graph('ae-experiment',btn('ae','Ordinary AE')+btn('vae','VAE')),builds=2,provenance='MEASURED · same held-out 7; same latent dimension and prior draw across AE and VAE',notes='Compare the observed digit encoded by the trained AE with a standard Gaussian latent decoded by that same network. Switch to the VAE using the same input and proposed prior draw. These actual outputs are not selected to make the AE look bad. Reconstruction training alone makes no promise about a chosen prior.',answer='A reconstruction uses a code the encoder produces. A proposed prior may visit different regions.')
 edit('three-objects',graph('three-distributions'),builds=3,idea='p and q describe latent variables; the decoder describes observations.')
 for id,title,phase,count in [('opaque-sample','Where should the gradient go?',0,1),('independent-noise','Put the randomness in a separate input',1,2),('computation-graph','One graph, from image to reconstruction loss',2,1),('sample-arithmetic','Follow one draw through the graph',3,3),('gradient-arithmetic','Now follow the same graph backwards',6,3),('code','Why does the encoder return log-variance?',9,2)]:
  edit(id,graph('reparameterization',btn('graph-prev','Previous step')+btn('graph-next','Next step')),title=title,builds=count,idea='',graph_phase=phase,provenance='ANALYTICAL / EXACT · hand-chosen scalar example; reconstruction gradients only')
 new('code','code-implementation','Four lines implement the same graph', '<pre class="code source-code">mu, logvar = encoder(x)\nstd = exp(0.5 * logvar)\neps = randn_like(std)\nz = mu + std * eps</pre>'+M(r'\sigma=\exp(\tfrac12\log\sigma^2)',True)+P('Differentiate with the sampled eps held fixed.','large'), notes='Point to the corresponding nodes on the preceding graph. The encoder learns mu and logvar. Exponentiation computes a positive standard deviation. randn_like supplies independent standard Gaussian noise. The addition and multiplication preserve the gradient path.', provenance='EXACT computation · elementwise diagonal-Gaussian reparameterization')
 edit('same-distribution',D('location-identity'),builds=3,idea='Use the same ε draws: scale first, then add μ.',notes='Start with standard Gaussian draws. Multiply those same draws by sigma=.5. Add mu=2. Scaling before shifting gives the desired mean mu; reversing these operations without adjustment would give sigma times mu. The identity is in distribution.')
