 new('likelihood','bernoulli-example','What probability did we assign to these four pixels?',graph('bernoulli'),builds=4,provenance='ANALYTICAL / EXACT · four binary observations; independent Bernoulli likelihood',notes='For an observed one use p; for zero use 1-p. Multiply the four probabilities or add their negative logarithms. We sum over pixels in the MNIST experiment; a mean would divide by four here.',answer=f'The sum is {N["bernoulli"]["sum_nats"]:.3f} nats; the mean is {N["bernoulli"]["mean_nats"]:.3f}.')
 edit('kl-arithmetic',graph('kl-worked'),builds=6,idea='',notes='Substitute the mean, variance, and log variance in separate steps. Compute the bracket, then multiply by one-half. Only after that move to mu=0 and sigma=1. Equality is the minimum of this KL term alone, not a requirement that a trained VAE ignore x.')
 edit('full-vae',graph('vae-mother'),builds=3,idea='Reconstruction and KL both send gradients to the encoder.')
 edit('train-generate',graph('vae-train-generate'),builds=2,idea='To generate, draw z from the prior and keep the decoder.')
