 new('measured-models','measured-generation','What happens when we draw from the prior?',O(P('VAE-2: decoder probabilities','label purple')+I('vae2-common-prior.png','big-strip')+P('VAE-16: decoder probabilities','label teal')+I('vae16-common-prior.png','big-strip'),0)+O(P('VAE-2: sampled binary pixels','label purple')+I('vae2-common-draws.png','big-strip')+P('VAE-16: sampled binary pixels','label teal')+I('vae16-common-draws.png','big-strip'),1),builds=2,notes='Use the same prior vectors for the mean images and their binary draws within each model. Dimensions differ across models. These eight draws were fixed before inspection. Blurry means express uncertain Bernoulli pixels; binary draws can be noisy.',provenance='MEASURED · saved checkpoints; prior seed 667; Bernoulli seed 668; no selection')
 edit('latent-plane','<div class="interactive" data-kind="explorer"><div class="plot"></div><div class="readout"></div><div class="controls">'+btn('fallback','Use recorded fallback')+btn('sample','Draw z from prior')+'</div></div>',idea='',notes='The large plane is the saved 25 by 25 grid. Choose a point to run the saved decoder locally. Inspect a 3 by 3 neighborhood and the same selected point under the prior. Arrow keys move .1. Recorded fallback snaps all outputs to measured grid coordinates and labels them. The prior density is a density over z, not digit likelihood.')
 edit('paths-and-curves',D('interpolation',slider('t','path position t',0,1,0,.025)),builds=1,title='What changes between this 7 and this 2?',notes='The path linearly interpolates the 16-dimensional posterior means of the first two test examples. All 41 displayed decoder means were computed with the checkpoint. A two-dimensional line represents t, not a projection of the full latent space. The two endpoints and selected point stay marked.')
 new('paths-and-curves','training-curves','What changes when we train a larger latent representation?',I('training-curves.svg','training-wide')+P('Lower reconstruction loss alone does not establish better generation.','caption'),provenance='MEASURED · unchanged VAE-2 and VAE-16 training histories',notes='Read both vertical axes in nats per training example. The larger latent representation reduces reconstruction error in this run while using more KL. These are training curves. Held-out metrics remain in the appendix.',answer='The reconstruction and KL terms change together; neither alone measures sample quality.')
 for id,kind,builds in [('another-signal','gan-mother',1),('discriminator','gan-mother',2),('train-discriminator','gan-mother',3),('train-generator','gan-mother',3),('alternate','gan-toggle',2)]:
  edit(id,graph(kind,btn('D','TRAIN D')+btn('G','TRAIN G') if id=='alternate' else ''),builds=builds,idea='')
 edit('train-discriminator',notes='Hold G fixed. Generate examples and detach them. Compute the summed real/fake BCE terms, then backpropagate into D and update only its weights. The displayed scores are hand-chosen teaching values; the later snapshots come from a separately recorded training run.')
 new('alternate','gan-numbers','What do these two losses ask for?',graph('gan-numbers'),builds=3,provenance='ANALYTICAL / EXACT · hand-chosen scores D(x)=0.9, D(G(z))=0.2',notes='Sum one real and one fake negative log probability for D. The non-saturating generator minimizes minus log D(fake). D is a classical sigmoid probability of source membership under its training problem, not a calibrated measure of objective realism. A WGAN critic has a different objective and interpretation.',answer='D wants real scores high and fake scores low. G wants D(fake) high.')
 new('gan-numbers','gan-training','What does alternating training do to the points?',D('gan-training',slider('snapshot','saved snapshot',0,4,0,1)),builds=5,provenance='MEASURED TRAINING OUTPUT · one fixed-seed 2D GAN run on the eight-Gaussian distribution',notes='Advance through steps 0, 100, 500, 1000 and 2000. Both axes remain fixed. Coverage counts centers with at least ten of one thousand fixed prior samples within three component standard deviations. This threshold is a teaching diagnostic, not a calibrated benchmark. We show the single run as recorded, whether or not it collapses.',answer='Inspect both the shape of generated points and their coverage; the loss alone is insufficient.')
 edit('coverage',notes='Retain this deliberately constructed three-mode sampler to isolate the difference between plausible individual points and coverage. It is distinct from the measured GAN run on the preceding screen.')
 edit('invertible',D('flow',slider('amount','deformation',0,1,0,.05))+O(M(r'x=f(z)',True),0)+O(M(r'z=f^{-1}(x)',True),1),builds=2)
 edit('change-of-variables',graph('volume-stretch'),builds=3,idea='',notes='The forward map x=2z doubles interval length. Its probability mass stays fixed, so density halves. The inverse derivative is one-half. This explains the plus log absolute inverse Jacobian convention. Ordinary generators need not be invertible; a VAE encoder and decoder are not generally inverses. This is normalizing flow, not flow matching.')
