 edit('next',graph('bridge-reverse')+P('Could a learned model run this corruption process backwards?','large'),title='Can we learn to remove a little noise at a time?',idea='',notes='The reverse arrow poses a question. Replaying stored frames does not learn a reverse process or recover an original from pure noise. Leave the DDPM equations for Generative II.',provenance='ILLUSTRATIVE reverse question · same frames and photograph as Generative II')
 edit('ae-sampling',D('ae',btn('ae','Emphasize AE')+btn('vae','Emphasize VAE')),builds=2,idea='Reconstruction alone does not make AE codes match a chosen prior.')
