 # Nine named chapter dividers. Keep a separate randomness chapter within the VAE story.
 starts=[('recall','Why generate?','Can a model produce new examples?',5),('discrete','Learning a distribution','What can finite observations tell us about possible data?',12),('language','We already know one','Must each token or pixel wait for the previous one?',4),('sevens','From randomness to data','Can a simple prior lead to a complex image?',8),('encoder-distribution','The variational autoencoder','Which latent distribution explains this image?',5),('opaque-sample','Training through randomness','How will the gradient reach the encoder?',15),('two-requirements','Why two losses?','How do we reconstruct well and still sample?',17),('another-signal','Learning through a discriminator','Could a learned discriminator supply the training signal?',10),('invertible','Invertible generation','What other paths lead from randomness to data?',4)]
 for chapter,(before,title,question,minutes) in enumerate(starts):
  target=by[before];div=dict(target);div.update(id=f'chapter-{chapter}',title=title,body=f'<div class="chapter-number">{chapter:02}</div>'+P(question,'chapter-question')+P('How do we turn randomness into valid data?','chapter-thread'),builds=1,idea='',notes=f'Chapter transition. Budget {minutes} minutes including the following concepts. Ask: {question}',question=question,answer='Use the following examples to develop the answer.',provenance='ES667 · chapter question',source=None,chapter=True)
  slides.insert(slides.index(target),div)
 sec='00 · Why generate?'
 for s in slides:
  if s.get('chapter'):sec=f'{int(s["id"].split("-")[1]):02} · {s["title"]}'
  if not s['appendix']:s['section']=sec
